            Version::parse("1.2.3", VersionGrammar::SemVer).unwrap(),
        )]))
    }
    #[test]
    fn fresh_validation_rejects_manifest_change() {
        let (dir, runner) = fixture();
        let locator = crate::IgnoreWalkLocator::new(dir.path());
        let intent = build_release_intent(
